const INVOICES = { 4815: { owner: 'alice' }, 4816: { owner: 'bob' }, 4900: { owner: 'carol' } };
function runChecks(canAccess) {
  const alice = { user: 'alice', role: 'user' };
  const bob = { user: 'bob', role: 'user' };
  const root = { user: 'root', role: 'admin' };
  const anon = null;
  const cases = [
    [canAccess(alice, 4815) === true, 'owner reads own'],
    [canAccess(alice, 4816) === false, 'owner blocked from stranger (IDOR)'],
    [canAccess(bob, 4816) === true, 'other owner reads own'],
    [canAccess(root, 4900) === true, 'admin override'],
    [canAccess(alice, 9999) === false, 'unknown invoice denied'],
    [canAccess(anon, 4815) === false, 'no session denied'],
  ];
  const failed = cases.filter(function (c) { return !c[0]; });
  if (failed.length === 0) console.log('PASS deny-by-default: 6/6');
  else console.log('FAIL: ' + failed.map(function (c) { return c[1]; }).join('; '));
}
